E ,a.ADD_TO_CARTS ,a.ADD_TO_CART_VALUE ,a.LANDING_PAGE_VIEWS ,a.INITIATE_CHECKOUTS ,a.INITIATE_CHECKOUTS_VALUE ,b.campaign_name shopify_campaign_name ,a.Marketplace_ID ,a.sku ,coalesce(s.parent_sku,split(a.sku,\'-\') [offset(0)]) parent_sku ,coalesce(s.color_sku,case when REGEXP_CONTAINS(a.sku, r\'-.*-\') then concat(split(a.sku,\'-\') [offset(0)],\'-\',split(a.sku,\'-\') [offset(1)]) end) color_sku ,concat(\'<img src=\"\',s.image_url,\'\"width=\"40\">\') image ,safe_divide(shopify_revenue, count(1) over (partition by coalesce(a.date,b.date) ,lower(coalesce(a.campaign_name,b.campaign_name)) ,lower(coalesce(a.channel,b.channel)) ) ) shopify_revenue from maplemonk.TRASE_MARKETING_CONSOLIDATED_INTERMEDIATE a left join (select sku, parent_sku, color_sku, image_url from maplemonk.trase_sales_consolidated qualify row_number() over (partition by sku order by parent_sku desc,color_sku desc,image_url desc)=1) s on lower(a.sku) = lower(s.sku) full outer join (select cast(order_timestamp as date) date ,final_utm_campaign campaign_name ,upper(case when lower(final_utm_channel) like any (\'%paid social%\',\'%facebook%\', \'%instagram%\',\'%ig%\',\'%fb%\') then \'FACEBOOK\' when lower(final_utm_channel) like (\'%google%\') then \'GOOGLE\' end) channel ,sum(total_sales) shopify_revenue from maplemonk.TRASE_SHOPIFY_FACT_ITEMS where final_utm_channel is not null group by 1,2,3 ) b on lower(a.campaign_name) = lower(b.campaign_name) and a.date = b.date and lower(a.channel) = lower(b.channel);",
